async function saveSetupShortcut(page:Page,shortcut='Ctrl+Shift+5'){
 await expect(page.getByRole('heading',{name:'Choose your teacher dashboard shortcut'})).toBeVisible();
 await expect(page.getByLabel('Open teacher dashboard')).toHaveValue('Ctrl+Shift+5');
 if(shortcut!=='Ctrl+Shift+5')await page.getByLabel('Open teacher dashboard').selectOption(shortcut);
 await page.getByRole('button',{name:'Save Shortcut and Continue'}).click();
}
async function setup(page:Page){
 await page.goto('/',{waitUntil:'domcontentloaded'});
 await page.getByLabel('Teacher PIN',{exact:true}).fill('2468');
 await page.getByLabel('Confirm PIN').fill('2468');
 await page.getByRole('button',{name:'Continue',exact:true}).click();
 await saveSetupShortcut(page);
 await page.getByRole('button',{name:'Add Student Manually'}).click();
 for(const [index,[name,id]]of[['Fictional Student One','001482'],['Fictional Student Two','001937']].entries()){await page.getByLabel('Full name').fill(name);await page.getByLabel('Student ID').fill(id);await page.getByRole('button',{name:'Add Student',exact:true}).click();await expect(page.getByText(`${index+1} student${index?'s':''} currently added`)).toBeVisible()}
 await page.getByRole('button',{name:'Continue to App'}).click();
 await expect(page.getByText('Ready for class')).toBeVisible();
}
async function openTeacher(page:Page){await page.keyboard.press('Control+Shift+5');await expect(page.getByRole('dialog')).toBeVisible();await page.getByLabel('Teacher PIN').fill('2468');await page.getByRole('button',{name:'Continue'}).click();await expect(page.getByText('Teacher dashboard')).toBeVisible()}
async function keypad(page:Page,id:string){await page.getByRole('button',{name:'Add/remove my name from the bathroom line'}).click();for(const digit of id)await page.locator('.keypad').getByRole('button',{name:digit,exact:true}).click();await page.getByRole('button',{name:'Find me'}).click()}
async function changeActiveStart(page:Page,secondsAgo:number){await page.evaluate(async seconds=>{const request=indexedDB.open('ClassroomBathroomQueue');const database=await new Promise<IDBDatabase>((resolve,reject)=>{request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)});await new Promise<void>((resolve,reject)=>{const tx=database.transaction('queue','readwrite'),store=tx.objectStore('queue'),all=store.getAll();all.onsuccess=()=>{const active=all.result.find((x:any)=>x.status==='active');active.startedAt=new Date(Date.now()-seconds*1000).toISOString();store.put(active)};tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error)});database.close()},secondsAgo)}
async function addCompletedSession(page:Page,name:string,suffix:string,overLimit=false){await page.evaluate(async({name,suffix,overLimit})=>{const request=indexedDB.open('ClassroomBathroomQueue'),database=await new Promise<IDBDatabase>((resolve,reject)=>{request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)});await new Promise<void>((resolve,reject)=>{const tx=database.transaction(['students','sessions'],'readwrite'),students=tx.objectStore('students').getAll();students.onsuccess=()=>{const student=students.result.find((value:any)=>value.name===name),endedAt=new Date().toISOString(),startedAt=new Date(Date.now()-60_000).toISOString();tx.objectStore('sessions').put({id:`probation-${suffix}`,studentId:student.id,studentName:student.name,queuedAt:startedAt,startedAt,endedAt,durationSeconds:60,durationFormatted:'1:00',reachedWarning:overLimit,overLimit,status:'completed',passType:'bathroom',createdAt:endedAt,updatedAt:endedAt})};tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error)});database.close()},{name,suffix,overLimit})}
async function addTimedSession(page:Page,name:string,suffix:string,durationSeconds:number,passType:'bathroom'|'water'='bathroom'){await page.evaluate(async({name,suffix,durationSeconds,passType})=>{const request=indexedDB.open('ClassroomBathroomQueue'),database=await new Promise<IDBDatabase>((resolve,reject)=>{request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)});await new Promise<void>((resolve,reject)=>{const tx=database.transaction(['students','sessions'],'readwrite'),students=tx.objectStore('students').getAll();students.onsuccess=()=>{const student=students.result.find((value:any)=>value.name===name),endedAt=new Date().toISOString(),startedAt=new Date(Date.now()-durationSeconds*1000).toISOString();tx.objectStore('sessions').put({id:`weekly-${suffix}`,studentId:student.id,studentName:student.name,queuedAt:startedAt,startedAt,endedAt,durationSeconds,durationFormatted:`${Math.floor(durationSeconds/60)}:${String(durationSeconds%60).padStart(2,'0')}`,reachedWarning:false,overLimit:false,status:'completed',passType,createdAt:endedAt,updatedAt:endedAt})};tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error)});database.close()},{name,suffix,durationSeconds,passType})}
async function moveAllSessionsToPreviousWeek(page:Page){await page.evaluate(async()=>{const request=indexedDB.open('ClassroomBathroomQueue'),database=await new Promise<IDBDatabase>((resolve,reject)=>{request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)});await new Promise<void>((resolve,reject)=>{const tx=database.transaction('sessions','readwrite'),store=tx.objectStore('sessions'),all=store.getAll();all.onsuccess=()=>{for(const session of all.result){for(const field of['queuedAt','startedAt','endedAt','createdAt','updatedAt'])if(session[field])session[field]=new Date(new Date(session[field]).getTime()-8*86_400_000).toISOString();store.put(session)}};tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error)});database.close()})}

