 await addCompletedSession(page,'Fictional Student One','one',true);await page.reload();await page.getByRole('button',{name:'Start Bathroom Kiosk'}).click();await keypad(page,'001482');await expect(page.getByText(/1 more over-limit return within the rolling 30-day period/)).toBeVisible();await expect(page.getByRole('button',{name:'Add my name for the bathroom'})).toBeVisible();await page.getByRole('button',{name:'Back to home page'}).click();
 await addCompletedSession(page,'Fictional Student One','two',true);await page.reload();await page.getByRole('button',{name:'Start Bathroom Kiosk'}).click();await keypad(page,'001482');await expect(page.getByRole('heading',{name:'Bathroom-pass access in this app is temporarily suspended'})).toBeVisible();await expect(page.getByText('Raw overtime threshold (2)')).toBeVisible();await expect(page.getByText('Speak with your teacher if this is an emergency or you have an accommodation.')).toBeVisible();await expect(page.getByRole('button',{name:'Add my name for the bathroom'})).toHaveCount(0);
