 await page.getByRole('button',{name:'Settings',exact:true}).click();await page.getByRole('button',{name:'Export Encrypted Full Backup'}).click();await page.getByLabel('Backup password',{exact:true}).fill('correct horse battery');await page.getByLabel('Confirm backup password').fill('correct horse battery');const downloadReady=page.waitForEvent('download');await page.getByRole('button',{name:'Encrypt and Download'}).click();const download=await downloadReady,backupPath=testInfo.outputPath('probation-backup.json');await download.saveAs(backupPath);
