 await page.getByRole('button',{name:'Settings',exact:true}).click();await page.locator('input[type=file][accept*="json"]').setInputFiles(backupPath);await page.getByLabel('Backup password',{exact:true}).fill('correct horse battery');await page.getByLabel('Restore teacher PIN').fill('2468');await page.getByRole('button',{name:'Restore and Replace Current Data'}).click();await expect(page.getByText('Encrypted backup restored successfully.')).toBeVisible();await page.getByRole('button',{name:'Usage Limit',exact:true}).click();await page.locator('details.bathroom-pass-advanced').getByText('Advanced',{exact:true}).click();await expect(page.getByLabel('Enable automatic pass suspensions')).toBeChecked();await page.getByRole('button',{name:'Pass Suspension',exact:true}).click();const restoredRow=page.locator('.probation-row').filter({hasText:'Fictional Student One'});await expect(restoredRow).toContainText('Rolling 30-day automatic suspension');
