test('Aeries class associations, hidden schedule controls, and local-only operation',async({page})=>{
 await page.addInitScript(()=>{let fullscreen=false;Object.defineProperty(document,'fullscreenElement',{configurable:true,get:()=>fullscreen?document.documentElement:null});Element.prototype.requestFullscreen=async()=>{fullscreen=true;document.dispatchEvent(new Event('fullscreenchange'))};document.exitFullscreen=async()=>{fullscreen=false;document.dispatchEvent(new Event('fullscreenchange'))}});
 const remoteRequests:string[]=[];
 page.on('request',request=>{const url=new URL(request.url());if(!['127.0.0.1','localhost'].includes(url.hostname))remoteRequests.push(request.url())});
 await setup(page);
 await openTeacher(page);
 await page.getByRole('button',{name:'Roster',exact:true}).click();
 await page.locator('input[type=file][accept*="text/plain"]').setInputFiles({name:'aeries-roster.txt',mimeType:'text/plain',buffer:Buffer.from(aeriesFixture)});
 await page.getByRole('button',{name:'Import selected students'}).click();
 await page.getByRole('button',{name:'Settings'}).click();
 await expect(page.getByRole('heading',{name:'Switch Class / Period'})).not.toBeVisible();
 await expect(page.getByRole('heading',{name:'Bell Schedule'})).not.toBeVisible();
 const stored=await page.evaluate(async()=>{const request=indexedDB.open('ClassroomBathroomQueue');const database=await new Promise<IDBDatabase>((resolve,reject)=>{request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)});const read=(store:string)=>new Promise<any[]>((resolve,reject)=>{const tx=database.transaction(store),get=tx.objectStore(store).getAll();get.onsuccess=()=>resolve(get.result);get.onerror=()=>reject(get.error)});return{classes:await read('classes'),enrollments:await read('enrollments'),settings:(await read('settings'))[0]}});
 expect(stored.classes).toHaveLength(2);
 expect(stored.enrollments).toHaveLength(2);
 expect(remoteRequests).toEqual([]);
 await page.getByRole('navigation').getByRole('button',{name:'Return to student mode'}).click();await page.getByRole('button',{name:'Start Bathroom Kiosk'}).click();await keypad(page,'170000');await expect(page.getByRole('heading',{name:'Thomas L Almond'})).toBeVisible();
});

test('Ctrl+Shift+6 clears only waiting students and Undo restores exact queue state',async({page})=>{
 await page.addInitScript(()=>{let fullscreen=false;Object.defineProperty(document,'fullscreenElement',{configurable:true,get:()=>fullscreen?document.documentElement:null});Element.prototype.requestFullscreen=async()=>{fullscreen=true;document.dispatchEvent(new Event('fullscreenchange'))};document.exitFullscreen=async()=>{fullscreen=false;document.dispatchEvent(new Event('fullscreenchange'))}});
 await setup(page);
 await page.getByRole('button',{name:'Start Bathroom Kiosk'}).click();
 await keypad(page,'001482');await page.getByRole('button',{name:'Add my name for the bathroom'}).click();
 await page.getByRole('button',{name:"I'm ready to use the bathroom"}).click();
 await keypad(page,'001937');await page.getByRole('button',{name:'Add my name for the bathroom'}).click();
 const before=await page.evaluate(async()=>{const request=indexedDB.open('ClassroomBathroomQueue'),database=await new Promise<IDBDatabase>((resolve,reject)=>{request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)});return await new Promise<any[]>((resolve,reject)=>{const tx=database.transaction('queue'),get=tx.objectStore('queue').getAll();get.onsuccess=()=>resolve(get.result);get.onerror=()=>reject(get.error)})});
 await page.keyboard.press('Control+Shift+6');
 await expect(page.getByText('1 waiting student removed.')).toBeVisible();
 await expect(page.getByRole('heading',{name:'Fictional Student One'})).toBeVisible();
 await expect(page.getByText('Fictional Student Two')).not.toBeVisible();
 await page.getByRole('button',{name:'Undo'}).click();
 await expect(page.getByText('Fictional Student Two')).toBeVisible();
 const after=await page.evaluate(async()=>{const request=indexedDB.open('ClassroomBathroomQueue'),database=await new Promise<IDBDatabase>((resolve,reject)=>{request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)});return await new Promise<any[]>((resolve,reject)=>{const tx=database.transaction('queue'),get=tx.objectStore('queue').getAll();get.onsuccess=()=>resolve(get.result);get.onerror=()=>reject(get.error)})});
 expect(after.sort((a,b)=>a.queuedAt.localeCompare(b.queuedAt))).toEqual(before.sort((a,b)=>a.queuedAt.localeCompare(b.queuedAt)));
});

